# Code generated by Claude
"""
Timing test of the pouring scene (B3): physics cost per step with balls, with and without the no-slip solver pass, at rest and during a kinematic pour. Physics only (no controller, no rendering).

    MUJOCO_GL=egl python experiments/pour_timing_test.py [--balls 0 30 40 50 60] [--noslip 10 0]

For each ball count and no-slip setting: load the task scene with the pouring objects, settle, time one second at rest, then time the whole pour of experiments/pour_helpers.py (10 s of
simulated time), and count where the balls end up. Real time at the 750 Hz physics rate is 1.33 ms per step; the pour's window maximum is the cost the policy loop would have to ride out.
"""

import argparse
import os
import resource
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from pour_helpers import hold_ctrl, run_pour, settle  # noqa: E402
from src.pour_scene import ball_counts  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import BEAKER_CFG, POUR_CFG  # noqa: E402

NO = {**BEAKER_CFG, "liquid_mass": 0.0}
REAL_MS = 1000.0 / 750.0


def main(args):
    print(f"real time at 750 Hz is {REAL_MS:.2f} ms per step; the pour is 10 s = 7500 steps\n")
    print(f"{'balls':>5} {'noslip':>6} | {'rest ms':>8} {'x real':>6} | {'pour ms':>8} {'x real':>6} {'worst 0.25 s':>12} {'x real':>6} {'contacts':>8} | {'transferred':>11} {'spilled':>7} | {'pour wall s':>11} {'RSS MB':>7}")
    for n in args.balls:
        for ns in args.noslip:
            cfg = {**POUR_CFG, "n_balls": n, "full": "first"}
            sim = load_task(cameras=False, pour=cfg)
            sim.model.opt.noslip_iterations = ns
            hold = settle(sim, 1.0)
            m, d = sim.model, sim.data
            ts = []
            for _ in range(750):
                hold_ctrl(d, hold)
                t0 = time.perf_counter()
                mujoco.mj_step(m, d)
                ts.append(time.perf_counter() - t0)
            rest = 1000 * float(np.mean(ts))
            r = run_pour(sim, hold, "task_beaker", "task_beaker_2")
            c = ball_counts(m, d, cfg, NO, "task_beaker", "task_beaker_2")
            rss = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss // 1024
            print(f"{n:5d} {ns:6d} | {rest:8.2f} {rest / REAL_MS:6.1f} | {r['mean_ms']:8.2f} {r['mean_ms'] / REAL_MS:6.1f} {r['max_ms']:12.2f} {r['max_ms'] / REAL_MS:6.1f} {r['max_contacts']:8d} | "
                  f"{c['transferred']:5d}/{n:<5d} {c['spilled']:7d} | {r['total_s']:11.1f} {rss:7d}", flush=True)
            del sim


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("--balls", type=int, nargs="+", default=[0, 30, 40, 50, 60])
    ap.add_argument("--noslip", type=int, nargs="+", default=[10, 0])
    main(ap.parse_args())
